// Parsers tested on real coursesu.com pages (test/fixtures/superu, regenerated by `npm run fixtures -- superu`).

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { SessionExpiredError, SiteBlockedError, TransientError, ValidationError } from "../../src/domain/errors.ts";
import { parseProductId } from "../../src/domain/product.ts";
import {
  parseCartPage,
  parseDisplayedPrice,
  parseMinimumOrder,
  parseProductPage,
  parseSearchPage,
  parseSlotInfoPage,
  parseSpokenPrice,
  parseUnitPrice,
} from "../../src/infrastructure/retailers/superu/parsers.ts";
import { fixture as read } from "../support/fake-http.ts";

const fixture = (name: string) => read("superu", name);
const TODAY = new Date(2026, 9, 24);

describe("prices", () => {
  it("reads the price spelled out for screen readers", () => {
    assert.equal(parseSpokenPrice("1 euros 34 centimes"), 134);
    assert.equal(parseSpokenPrice("0 euros 95 centimes"), 95);
    assert.equal(parseSpokenPrice("4 euros 72 au lieu de 7 euros 16"), 472);
    assert.equal(parseSpokenPrice("Ajouter au panier"), null);
  });

  it("reads a displayed price, thousands included", () => {
    assert.equal(parseDisplayedPrice("Total estimé* 61,78 € *"), 6178);
    assert.equal(parseDisplayedPrice("1 234,56 €"), 123456);
    assert.equal(parseDisplayedPrice("Offerts"), null);
  });

  it("reads a unit price", () => {
    assert.deepEqual(parseUnitPrice("1,90 €/kg"), { per: "kg", price: 190 });
    assert.deepEqual(parseUnitPrice("5,08 €/l"), { per: "l", price: 508 });
    assert.deepEqual(parseUnitPrice("0,17 €/pce"), { per: "piece", price: 17 });
    assert.equal(parseUnitPrice(""), null);
  });
});

describe("search page", () => {
  const spaghetti = parseSearchPage(200, fixture("search-spaghetti.html"));
  const lessive = parseSearchPage(200, fixture("search-lessive.html"));

  it("reads the 18 tiles, the reported total and the CSRF token", () => {
    assert.equal(spaghetti.products.length, 18);
    assert.equal(spaghetti.total, 44);
    assert.equal(spaghetti.csrfToken, "FIXTURE_CSRF");
  });

  it("reads identifier, label, price and price per kg", () => {
    const barilla = spaghetti.products.find((p) => p.id === "960853");
    assert.deepEqual(barilla, {
      available: true,
      id: "960853",
      name: "Pâtes Spaghetti N°5 BARILLA - 500g",
      price: 95,
      promotions: [],
      unitPrice: { per: "kg", price: 190 },
    });
  });

  it("reads a Carte U benefit", () => {
    const u = spaghetti.products.find((p) => p.id === "1177214");
    assert.deepEqual(u?.promotions, [
      {
        details: ["20% versés sur votre Carte U pour l'achat de ce produit.", "Soit 0,27€ versés sur votre Carte U."],
        kind: "loyalty",
        label: "Avantage Carte U",
        mechanic: { amount: 27, type: "loyalty_amount" },
        regularPrice: null,
        validUntil: "25/10",
      },
    ]);
  });

  it("reads an immediate discount with the struck-through price", () => {
    const bonux = lessive.products.find((p) => p.id === "3980337");
    assert.equal(bonux?.price, 574);
    const [promo] = bonux?.promotions ?? [];
    assert.equal(promo?.label, "Promotion");
    assert.equal(promo?.kind, "immediate");
    assert.equal(promo?.regularPrice, 871);
    assert.match(promo?.details[0] ?? "", /-34% de remise immédiate/);
    assert.deepEqual(promo?.mechanic, { percent: 34, type: "percent_off" });
  });

  it("keeps the single item's unit price, not the bundle's", () => {
    const chat = lessive.products.find((p) => p.id === "5119616");
    assert.deepEqual(chat?.unitPrice, { per: "l", price: 508 });
    assert.ok(chat?.promotions[0]?.details.some((d) => /2ème produit/.test(d)));
    assert.equal(chat?.promotions[0]?.kind, "multibuy");
    assert.deepEqual(chat?.promotions[0]?.mechanic, { nth: 2, percent: 80, type: "nth_percent_off" });
  });

  it("every product has a numeric identifier and a label", () => {
    for (const p of [...spaghetti.products, ...lessive.products]) {
      assert.match(p.id, /^\d+$/);
      assert.ok(p.name.length > 0);
    }
  });

  it("detects an unavailable product", () => {
    const html = `<div class="product-tile"><div data-pid="42"></div><div class="product-name">Bananes</div>
      <span class="sr-only">1 euros 99 centimes</span><p>Produit indisponible</p></div>`;
    assert.equal(parseSearchPage(200, html).products[0]?.available, false);
  });

  it("ignores the mini-cart tiles", () => {
    const html = `<div class="product-tile mini-cart"><div data-pid="42"></div><div class="product-name">X</div></div>`;
    assert.deepEqual(parseSearchPage(200, html).products, []);
  });
});

describe("cart page", () => {
  const cart = parseCartPage(200, fixture("cart.html"));

  it("reads lines, quantities, line totals, unit prices and estimated total", () => {
    assert.equal(cart.lines.length, 4);
    assert.deepEqual(cart.lines[0], {
      lineTotal: 970,
      name: "Oeufs frais - Plateau de 30",
      productId: "6352025",
      quantity: 2,
      unitPrice: { per: "piece", price: 17 },
    });
    assert.equal(cart.total, 6178);
    assert.equal(cart.csrfToken, "FIXTURE_CSRF");
  });

  it("accepts an empty cart", () => {
    assert.deepEqual(parseCartPage(200, "<html><body><h1>Mon panier</h1></body></html>").lines, []);
  });
});

describe("order conditions", () => {
  it("reads store, booked slot and next slots", () => {
    assert.deepEqual(parseSlotInfoPage(200, fixture("slot-info.html"), TODAY), {
      bookedSlot: { end: "2026-10-25T09:00", label: "Dim. 25/10 de 08h30 à 09h00", start: "2026-10-25T08:30" },
      nextSlots: [
        {
          available: true,
          full: false,
          mode: "drive",
          slot: { end: null, label: "Dimanche 25 octobre à 08h00", start: "2026-10-25T08:00" },
        },
        {
          available: true,
          full: false,
          mode: "delivery",
          slot: { end: null, label: "Dimanche 25 octobre à 07h00", start: "2026-10-25T07:00" },
        },
      ],
      store: "super u ville test",
    });
  });

  it("no booked slot and no usable information", () => {
    const html = `<div data-footer-slots-info="pas du json"><p data-store-description-delivery>Choisir un créneau</p></div>`;
    assert.deepEqual(parseSlotInfoPage(200, html, TODAY), { bookedSlot: null, nextSlots: [], store: null });
  });

  it("full slot without a label", () => {
    const html = `<div data-footer-slots-info='{"drive":{"slotAvailable":false,"slotFull":true},"delivery":"?"}'></div>`;
    const page = parseSlotInfoPage(200, html, TODAY);
    assert.deepEqual(page.nextSlots, [{ available: false, full: true, mode: "drive", slot: null }]);
  });

  it("reads the minimum order per mode", () => {
    assert.deepEqual(parseMinimumOrder(200, fixture("cart.html")), [
      { amount: 5000, mode: "drive" },
      { amount: 5000, mode: "delivery" },
    ]);
    assert.deepEqual(parseMinimumOrder(200, `<li class="cart-minimum-amount">Retrait drive : 35,50 €</li>`), [
      { amount: 3550, mode: "drive" },
    ]);
    assert.throws(() => parseMinimumOrder(403, ""), SiteBlockedError);
  });
});

describe("product page", () => {
  const id = (raw: string) => parseProductId(raw);

  it("reads the label and the ingredients, allergens and traces included", () => {
    const pesto = parseProductPage(200, fixture("product-pesto.html"), id("3870987"));
    assert.equal(pesto.name, "Sauce Pesto Genovese au basilic frais BARILLA - 190g");
    assert.match(pesto.ingredients ?? "", /^Huile de tournesol, basilic 30%/);
    assert.match(pesto.ingredients ?? "", /Parmigiano Reggiano AOP 5% \(LAIT\)/);
    assert.match(pesto.ingredients ?? "", /Peut contenir des traces d'autres FRUITS À COQUE\.$/);
    assert.equal(pesto.origin, null);
  });

  it('removes the "Ingrédients :" prefix repeated in the text', () => {
    const jambon = parseProductPage(200, fixture("product-jambon.html"), id("4074234"));
    assert.match(jambon.ingredients ?? "", /^jambon de porc \(origine : France\), eau, sel/);
  });

  it("raw product: origin without ingredients", () => {
    const poulet = parseProductPage(200, fixture("product-poulet.html"), id("5144285"));
    assert.equal(poulet.ingredients, null);
    assert.equal(poulet.origin, "Né, élevé et abattu en France");
  });

  it("product page without a composition section", () => {
    const page = parseProductPage(200, "<h1>Poireaux vrac</h1><div id='product-details'></div>", id("1"));
    assert.deepEqual(page, { allergens: null, id: "1", ingredients: null, name: "Poireaux vrac", origin: null });
  });

  it("unknown product, unreadable page and anti-bot", () => {
    assert.throws(() => parseProductPage(410, "<html></html>", id("9")), ValidationError);
    assert.throws(() => parseProductPage(200, "<html></html>", id("9")), TransientError);
    assert.throws(() => parseProductPage(403, "", id("9")), SiteBlockedError);
  });
});

describe("blocking states", () => {
  it("anti-bot: 403, 429 or captcha page", () => {
    assert.throws(() => parseSearchPage(403, ""), SiteBlockedError);
    assert.throws(() => parseCartPage(429, ""), SiteBlockedError);
    assert.throws(
      () => parseSearchPage(200, "<html><script src='https://ct.captcha-delivery.com'></script>"),
      SiteBlockedError,
    );
  });

  it("expired session", () => {
    assert.throws(() => parseSearchPage(200, "<p>Votre créneau arrivé à terme</p>"), SessionExpiredError);
    assert.throws(() => parseCartPage(200, "<a>Se connecter</a>"), SessionExpiredError);
  });
});
